def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    # find seed
    seed=None
    for r in range(H):
        for c in range(W):
            if g[r][c]==2: seed=(r,c)
    # initial direction: toward interior
    r,c=seed
    if r==0: d=(1,0)
    elif r==H-1: d=(-1,0)
    elif c==0: d=(0,1)
    else: d=(0,-1)
    def beam(r,c,d):
        stack=[(r,c,d)]
        while stack:
            r,c,d=stack.pop()
            while True:
                out[r][c]=2
                nr,nc=r+d[0],c+d[1]
                if not (0<=nr<H and 0<=nc<W): break
                if g[nr][nc]==8:
                    # split perpendicular
                    p=(-d[1],d[0]); q=(d[1],-d[0])
                    for pd in (p,q):
                        br,bc=r+pd[0],c+pd[1]
                        if 0<=br<H and 0<=bc<W and g[br][bc]!=8:
                            # walk along wall until gap in wall or edge
                            cr,cc=br,bc
                            while 0<=cr<H and 0<=cc<W:
                                out[cr][cc]=2
                                wr,wc=cr+d[0],cc+d[1]  # wall side cell
                                fr,fc=cr+pd[0],cc+pd[1]  # forward
                                if 0<=wr<H and 0<=wc<W and g[wr][wc]==0:
                                    stack.append((cr,cc,(d[0],d[1])))  # turn into gap
                                    break
                                if not (0<=fr<H and 0<=fc<W) or g[fr][fc]==8:
                                    break
                                cr,cc=fr,fc
                    break
                r,c=nr,nc
    beam(r,c,d)
    return out

