def transform2(g, debug=False):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seed=None
    for r in range(H):
        for c in range(W):
            if g[r][c]==2: seed=(r,c)
    r,c=seed
    if r==0: d=(1,0)
    elif r==H-1: d=(-1,0)
    elif c==0: d=(0,1)
    else: d=(0,-1)
    def walk(cr,cc,pd,d):
        path=[]
        while 0<=cr<H and 0<=cc<W:
            out[cr][cc]=2
            path.append((cr,cc))
            wr,wc=cr+d[0],cc+d[1]
            fr,fc=cr+pd[0],cc+pd[1]
            if 0<=wr<H and 0<=wc<W and g[wr][wc]==0:
                if debug: print('walk pd',pd,'path',path,'-> turn at',(cr,cc))
                return (cr,cc,d)
            if not (0<=fr<H and 0<=fc<W) or g[fr][fc]==8:
                if debug: print('walk pd',pd,'path',path,'-> dead end')
                return None
            cr,cc=fr,fc
        if debug: print('walk pd',pd,'path',path,'-> edge')
        return None
    stack=[(r,c,d)]
    while stack:
        r,c,d=stack.pop()
        if debug: print('beam from',(r,c),'dir',d)
        while True:
            out[r][c]=2
            nr,nc=r+d[0],c+d[1]
            if not (0<=nr<H and 0<=nc<W): break
            if g[nr][nc]==8:
                if debug: print(' split at',(r,c))
                for pd in ((-d[1],d[0]),(d[1],-d[0])):
                    br,bc=r+pd[0],c+pd[1]
                    if 0<=br<H and 0<=bc<W and g[br][bc]!=8:
                        res=walk(br,bc,pd,d)
                        if res: stack.append(res)
                break
            r,c=nr,nc
    return out

